// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type GrowingUsersProps = Record<string, any>;

const GrowingUsers: React.FC<GrowingUsersProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 3,
  targetNumber = 3000,
  numberColor = "#0f172a",
  iconColor = "#94a3b8",
  iconCount = 80,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation timing
  // We complete the main counting and spawning animations at 75% of the total duration to allow it to rest
  const animationDurationFrames = Math.max(1, fps * durationInSeconds * 0.75);

  // Counter logic
  const currentNumber = Math.floor(
    interpolate(frame, [0, animationDurationFrames], [0, targetNumber], {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    })
  );

  const formattedNumber = currentNumber.toLocaleString("en-US");

  // Initial pop-in scale for the main text
  const textScale = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1 },
  });

  const minDimension = Math.min(width, height);
  
  // Independent X and Y radii map the circular distribution to an ellipse optimized for 9:16
  const baseRadiusX = width * 0.28;
  const spreadRangeX = width * 0.18;
  const baseRadiusY = height * 0.12;
  const spreadRangeY = height * 0.28;

  // Generate deterministic icon positions
  const icons = useMemo(() => {
    const items = [];
    for (let i = 0; i < iconCount; i++) {
      // Uniform random angle
      const angle = random(`angle-${i}`) * Math.PI * 2;
      // Square root of a random number ensures uniform distribution within the area
      const rDist = Math.sqrt(random(`dist-${i}`));
      // Base scale adds slight visual variety to the icons
      const baseScale = 0.6 + random(`scale-${i}`) * 0.6;

      items.push({ angle, rDist, baseScale, id: i });
    }
    // Sort by distance so they spawn radially from the center outwards
    return items.sort((a, b) => a.rDist - b.rDist);
  }, [iconCount]);

  // Constrain font size based on width so long numbers don't clip horizontally in portrait
  const fontSize = width * 0.15;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Absolute container so child coordinate 0,0 is perfectly centered */}
      <div
        style={{
          position: "absolute",
          width: 0,
          height: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {icons.map((icon, index) => {
          // Stagger the spawning of each icon based on its radial distance (sorted index)
          const delay = interpolate(
            index,
            [0, Math.max(1, iconCount - 1)],
            [0, animationDurationFrames * 0.8]
          );
          const iconFrame = frame - delay;

          // Spring physics for popping in
          const scaleSpring = spring({
            frame: iconFrame,
            fps,
            config: { damping: 12, mass: 0.8 },
          });

          // Gentle continuous outward drift after spawning, scaled independently to preserve ellipse shape
          const driftX = interpolate(iconFrame, [0, fps * 2], [0, width * 0.04], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const driftY = interpolate(iconFrame, [0, fps * 2], [0, height * 0.04], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const currentRadiusX = baseRadiusX + icon.rDist * spreadRangeX + driftX;
          const currentRadiusY = baseRadiusY + icon.rDist * spreadRangeY + driftY;

          const x = Math.cos(icon.angle) * currentRadiusX;
          const y = Math.sin(icon.angle) * currentRadiusY;

          const opacity = interpolate(iconFrame, [0, 10], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          // Slightly larger icon base size for vertical layout
          const size = minDimension * 0.055;

          return (
            <div
              key={icon.id}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: size,
                height: size,
                transform: `translate(-50%, -50%) scale(${scaleSpring * icon.baseScale})`,
                opacity,
                color: iconColor,
                transition: "none",
              }}
            >
              {/* Minimal Human Silhouette SVG */}
              <svg viewBox="0 0 24 24" fill="currentColor" style={{ width: "100%", height: "100%", display: "block" }}>
                <path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" />
              </svg>
            </div>
          );
        })}
      </div>

      {/* Center Target Number */}
      <div
        style={{
          position: "relative",
          fontSize,
          fontWeight: 800,
          color: numberColor,
          transform: `scale(${textScale})`,
          transition: "none",
          textShadow: `0px 4px 16px ${backgroundColor}B3`, // Drop shadow blends with background color
          zIndex: 10,
          textAlign: "center",
          lineHeight: 1,
          letterSpacing: "-0.02em",
        }}
      >
        {formattedNumber}
      </div>
    </AbsoluteFill>
  );
};

export default GrowingUsers;